import { SORT_DIRECTION } from '../constants';
import { isMobile } from '../helpers/browser';
import type { UserSettings } from '../interfaces/drive/userSettings';
import { LayoutSetting, SortSetting } from '../interfaces/drive/userSettings';

export const MB = 1024 * 1024;
export const FOLDER_PAGE_SIZE = 150;
export const BATCH_REQUEST_SIZE = 50;
export const FILE_CHUNK_SIZE = 4 * MB;
export const MEMORY_DOWNLOAD_LIMIT = (isMobile() ? 100 : 500) * MB;
export const HARDWARE_CONCURRENCY = (typeof window !== 'undefined' && window.navigator?.hardwareConcurrency) || 1;
// openpgp.js creates hardwareConcurrency of web workers to do decryption.
// Using less threads for download means we don't use available potential.
// Using more threads will not speed things up much because thread in this
// context is not real thread but concurrently running downloads in the main
// thread.
// In the future, with the openpgp.js v5, we will create web workers manually.
// That will allow us to create more workers and keep download and decryption
// part in the same thread to save some data exchanges between threads.
// We could really allow more workers than available CPUs, because decryption
// is done on the stream as data comes in, i.e., not that heavy operation.
// Of course, we cannot allow, lets say, twice as many workers per download
// of one file but for all downloads to not kill user's device. Ideally, we
// want to make download of one file as fast as possible, but limit it to the
// same speed with more ongoing downloads or uploads.
export const MAX_THREADS_PER_DOWNLOAD = HARDWARE_CONCURRENCY;
export const MAX_THREADS_PER_REQUEST = 5;
export const DEFAULT_SORT_FIELD = 'ModifyTime';
export const DEFAULT_SORT_ORDER: SORT_DIRECTION = SORT_DIRECTION.DESC;

export const DEFAULT_USER_SETTINGS: UserSettings = {
    Layout: LayoutSetting.List,
    Sort: SortSetting.ModifiedDesc,
    RevisionRetentionDays: 0,
};

export const UPLOAD_TIMEOUT = 90000;
export const DOWNLOAD_TIMEOUT = 90000;
export const DOWNLOAD_RETRIES_ON_TIMEOUT = 3;
export const EXPENSIVE_REQUEST_TIMEOUT = 60000;
export const MAX_NAME_LENGTH = 255;
export const MAX_SHARED_URL_PASSWORD_LENGTH = 50;

export const SHARE_GENERATED_PASSWORD_LENGTH = 12;

export const DEFAULT_SHARE_MAX_ACCESSES = 0; // Zero means unlimited.

export const MAX_SAFE_UPLOADING_FILE_COUNT = 500;
export const MAX_SAFE_UPLOADING_FILE_SIZE = 5 * 1024 * 1024 * 1024; // GB

export const CUSTOM_DATA_FORMAT = 'pd-custom';

export const THUMBNAIL_MAX_SIDE = 512; // in pixels
export const THUMBNAIL_MAX_SIZE = 60 * 1024; // in bytes, 60kB

export const HD_THUMBNAIL_MAX_SIDE = 1920; // in pixels
export const HD_THUMBNAIL_MAX_SIZE = 1024 * 1024; // in bytes, 1mB

import type { ReactElement } from 'react';

import { c, msgid } from 'ttag';

import {
    BRAND_NAME,
    CALENDAR_APP_NAME,
    CALENDAR_SHORT_APP_NAME,
    CYCLE,
    DRIVE_APP_NAME,
    DRIVE_SHORT_APP_NAME,
    MAIL_APP_NAME,
    MAIL_SHORT_APP_NAME,
    PASS_SHORT_APP_NAME,
    PLANS,
    PLAN_NAMES,
    VPN_SHORT_APP_NAME,
} from '@proton/shared/lib/constants';
import { getPremiumPasswordManagerText } from '@proton/shared/lib/helpers/checkout';
import humanSize from '@proton/shared/lib/helpers/humanSize';
import { getPremium } from '@proton/shared/lib/helpers/premium';

import type { IconName } from '../../../components/icon';

export const getMonthFreeText = (n: number) => {
    return c('specialoffer: Deal').ngettext(msgid`${n} month FREE`, `${n} months FREE`, n);
};

import { c } from 'ttag';

import { Icon, Info, StripedItem, StripedList } from '@proton/components';
import { CALENDAR_APP_NAME, DRIVE_APP_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';
import humanSize from '@proton/shared/lib/helpers/humanSize';

const ReferralFeaturesList = () => {
    const storageSize = humanSize({ bytes: 15 * 1024 ** 3, fraction: 0 });
    return (
        <StripedList>
            <StripedItem left={<Icon className="color-success" name="storage" size={5} />}>
                {c('bf2023: Deal details').t`${storageSize} storage`}
                <Info
                    className="ml-2"
                    title={c('Info')
                        .t`Storage space is shared across ${MAIL_APP_NAME}, ${CALENDAR_APP_NAME}, and ${DRIVE_APP_NAME}.`}
                />
            </StripedItem>
            <StripedItem left={<Icon className="color-success" name="envelope" size={5} />}>
                {c('Info').t`10 email addresses`}
import humanSize, { shortHumanSize } from '@proton/shared/lib/helpers/humanSize';

describe('humanSize', () => {
    it('should 0 bytes correctly', () => {
        expect(humanSize({ bytes: 0 })).toEqual('0 bytes');
    });
    it('should 0 GB correctly', () => {
        expect(humanSize({ bytes: 0, unit: 'GB' })).toEqual('0.00 GB');
    });
    it('should 1.5 GB correctly', () => {
        expect(humanSize({ bytes: 1024 * 1024 * 1024 + 1024 * 1024 * 500, unit: 'GB', fraction: 0 })).toEqual('1.5 GB');
    });
    it('should 1.5 GB correctly', () => {
        expect(
            humanSize({
                bytes: 1024 * 1024 * 1024 + 1024 * 1024 * 500,
                truncate: true,
                unit: 'GB',
                fraction: 0,
            })
        ).toEqual('1 GB');
    });
    it('should 1 GB correctly', () => {
        expect(humanSize({ bytes: 1024 * 1024 * 1024, unit: 'GB', fraction: 0 })).toEqual('1 GB');
    });
    it('should 1.0 GB correctly', () => {
        expect(humanSize({ bytes: 1024 * 1024 * 1024, unit: 'GB', fraction: 1 })).toEqual('1.0 GB');
    });

    it('should show max correctly', () => {
        (
            [
                { max: 'B', expectation: '1099511627776 bytes' },
                { max: 'KB', expectation: '1073741824 KB' },
                { max: 'MB', expectation: '1048576 MB' },
                { max: 'GB', expectation: '1024 GB' },
                { max: 'TB', expectation: '1 TB' },
            ] as const
        ).forEach(({ max, expectation }) => {
            expect(
                humanSize({
                    bytes: 1024 * 1024 * 1024 * 1024,
                    unitOptions: { max },
                    fraction: 0,
                })
            ).toEqual(expectation);
        });
    });
});

describe('shortHumanSize', () => {
    it('should show 0 bytes correctly', () => {
        expect(shortHumanSize(0)).toEqual('0 bytes');
    });
    it('should show 10 bytes correctly', () => {
        expect(shortHumanSize(10)).toEqual('10 bytes');
    });
    it('should show 10 KB correctly', () => {
        expect(shortHumanSize(1024 * 10)).toEqual('10 KB');
    });
    it('should show 10.5 KB correctly', () => {
        expect(shortHumanSize(1024 * 10)).toEqual('10 KB');
    });
    it('should show 10 MB correctly', () => {
        expect(shortHumanSize(1024 * 1024 * 10)).toEqual('10 MB');
    });
    it('should show 10.5 MB correctly', () => {
        expect(shortHumanSize(1024 * 1024 * 10 + 1024 * 500)).toEqual('10 MB');
    });
    it('should show 1.5 GB correctly', () => {
        expect(shortHumanSize(1024 * 1024 * 1024 + 1024 * 1024 * 500)).toEqual('1.5 GB');
    });
    it('should show 1 GB correctly', () => {
        expect(shortHumanSize(1024 * 1024 * 1024)).toEqual('1.0 GB');
    });
});

